// Where every exit and house door goes. Pure: no three, no DOM. Coordinates are the ones stored on the ZoneDef (world space).

/** The part of a zone this needs. A game's `ZoneDef` fits. */
export interface ZoneLike {
  id: string;
  name: string;
  indoor?: boolean;
  exits: readonly { x: number; z: number; to: string; arriveX: number; arriveZ: number; label: string; door?: boolean }[];
}

export interface DoorLink {
  /** The zone the exit stands in. */
  zone: string;
  /** Index into that zone's `exits`. */
  index: number;
  label: string;
  /** 'door' = a house door generated by the game; 'exit' = a zone exit. */
  kind: 'exit' | 'door';
  from: { x: number; z: number };
  to: string;
  toName: string;
  arrive: { x: number; z: number };
  /** false when `to` is not a zone the editor knows. */
  destKnown: boolean;
  destIndoor: boolean;
}

/** One link per exit of every zone, in zone then exit order. */
export function doorLinks(zones: Readonly<Record<string, ZoneLike>>): DoorLink[] {
  const out: DoorLink[] = [];
  for (const z of Object.values(zones)) {
    z.exits.forEach((e, index) => {
      const dest = zones[e.to];
      out.push({
        zone: z.id, index, label: e.label, kind: e.door ? 'door' : 'exit',
        from: { x: e.x, z: e.z }, to: e.to, toName: dest ? dest.name : '(unknown zone)',
        arrive: { x: e.arriveX, z: e.arriveZ }, destKnown: dest !== undefined, destIndoor: dest?.indoor === true,
      });
    });
  }
  return out;
}

/** The links that stand in one zone. */
export const linksIn = (links: readonly DoorLink[], zone: string): DoorLink[] => links.filter((l) => l.zone === zone);

/** The links for the editor's current state: the game's own zones, with the editor's (possibly edited) zones on top. Empty when the
 * adapter has no `doorZones`. */
export function contextDoorLinks(ctx: { adapter: { doorZones?(): Record<string, ZoneLike> }; zones: object }): DoorLink[] {
  if (!ctx.adapter.doorZones) return [];
  return doorLinks({ ...ctx.adapter.doorZones(), ...(ctx.zones as Record<string, ZoneLike>) });
}
